import sys

def matches(pattern, good_letters, query):
    good_set = set(good_letters)
    star_index = pattern.find('*')

    if star_index == -1:
        if len(pattern) != len(query):
            return False
        for p, q in zip(pattern, query):
            if p != '?' and p != q:
                return False
            if p == '?' and q not in good_set:
                return False
        return True
    else:
        prefix = pattern[:star_index]
        suffix = pattern[star_index + 1:]
        prefix_len = len(prefix)
        suffix_len = len(suffix)

        if len(query) < prefix_len + suffix_len:
            return False

        for i in range(len(query) - suffix_len + 1):
            if query[:i] == prefix and query[i + suffix_len:] == suffix:
                middle = query[i:i + suffix_len]
                if all(c in good_set or c not in good_set for c in middle):
                    return True
        return False

def main():
    import sys
    input = sys.stdin.read().splitlines()
    good_letters = input[0]
    pattern = input[1]
    n = int(input[2])
    queries = input[3:3+n]
    results = []
    for query in queries:
        results.append('YES' if matches(pattern, good_letters, query) else 'NO')
    print('\n'.join(results))

main()
